N=18
inp=[[1]*N for _ in range(N)]
rows={4:[4,5],5:[4,5],6:[5,9],7:[5,7,8,9,10,11],8:[5,9,10],9:list(range(4,11)),10:[4,5,9,10,11,12,13],11:[11,12]}
for r,cs in rows.items():
 for c in cs: inp[r][c]=7
inp[0][8]=2; inp[8][17]=2
out=[[1]*N for _ in range(N)]
# quadrant cells excluding beam lines; pack to corner by bounding boxes
quads=[('tl',[(r,c) for r in range(8) for c in range(8) if inp[r][c]==7]),
 ('tr',[(r,c) for r in range(8) for c in range(9,18) if inp[r][c]==7]),
 ('bl',[(r,c) for r in range(9,18) for c in range(8) if inp[r][c]==7]),
 ('br',[(r,c) for r in range(9,18) for c in range(9,18) if inp[r][c]==7])]
for name,cells in quads:
 if not cells: continue
 rs=[r for r,c in cells]; cs=[c for r,c in cells]
 if name=='tl': dr=-min(rs); dc=-min(cs)
 if name=='tr': dr=-min(rs); dc=17-max(cs)
 if name=='bl': dr=17-max(rs); dc=-min(cs)
 if name=='br': dr=17-max(rs); dc=17-max(cs)
 for r,c in cells: out[r+dr][c+dc]=7
# retain beam line 7s and draw 2 on empty cells
for r in range(N):
 if inp[r][8]==7: out[r][8]=7
 else: out[r][8]=2
for c in range(N):
 if inp[8][c]==7: out[8][c]=7
 else: out[8][c]=2
# ensure marker 2s
out[0][8]=2; out[8][17]=2
print('\n'.join(' '.join(map(str,row)) for row in out))

# Find 4-connected components of 7s off the two ray lines, per quadrant, then corner-pack each separately.
from collections import deque
coords_by={'tl':[(r,c) for r in range(8) for c in range(8) if inp[r][c]==7], 'tr':[(r,c) for r in range(8) for c in range(9,18) if inp[r][c]==7], 'bl':[(r,c) for r in range(9,18) for c in range(8) if inp[r][c]==7], 'br':[(r,c) for r in range(9,18) for c in range(9,18) if inp[r][c]==7]}
compout=[[1]*18 for _ in range(18)]
for name,cells in coords_by.items():
 rem=set(cells)
 while rem:
  q=[rem.pop()]; comp=[]
  while q:
   x=q.pop(); comp.append(x)
   for y in ((x[0]-1,x[1]),(x[0]+1,x[1]),(x[0],x[1]-1),(x[0],x[1]+1)):
    if y in rem: rem.remove(y); q.append(y)
  rs=[r for r,c in comp];cs=[c for r,c in comp]
  dr= -min(rs) if name in ('tl','tr') else 17-max(rs)
  dc= -min(cs) if name in ('tl','bl') else 17-max(cs)
  print(name,comp,'shift',dr,dc)
  for r,c in comp:
   compout[r+dr][c+dc]=7
# beams and retain 7 cells on beam
for r in range(10):compout[r][8]=7 if inp[r][8]==7 else 2
for c in range(5,18):compout[8][c]=7 if inp[8][c]==7 else 2
print('\n'.join(' '.join(map(str,row)) for row in compout))
